{"file_path": "src/components/ats/ATSWarning.tsx", "initial_content": "import { AlertCircle, AlertTriangle, Info } from 'lucide-react'
import { ATSCheck } from '../../types/ats'

interface ATSWarningProps {
  check: ATSCheck
  compact?: boolean
}

export default function ATSWarning({ check, compact = false }: ATSWarningProps) {
  const getIcon = () => {
    switch (check.severity) {
      case 'critical':
        return <AlertCircle className="w-4 h-4" />
      case 'warning':
        return <AlertTriangle className="w-4 h-4" />
      case 'info':
        return <Info className="w-4 h-4" />
    }
  }

  const getColors = () => {
    switch (check.severity) {
      case 'critical':
        return 'bg-red-50 border-red-200 text-red-800'
      case 'warning':
        return 'bg-yellow-50 border-yellow-200 text-yellow-800'
      case 'info':
        return 'bg-blue-50 border-blue-200 text-blue-800'
    }
  }

  if (compact) {
    return (
      <div className={`flex items-start gap-2 p-2 rounded border text-xs ${getColors()}`}>
        {getIcon()}
        <div className="flex-1">
          <p className="font-medium">{check.message}</p>
        </div>
      </div>
    )
  }

  return (
    <div className={`flex items-start gap-3 p-3 rounded-lg border ${getColors()}`}>
      {getIcon()}
      <div className="flex-1">
        <p className="text-sm font-medium mb-1">{check.message}</p>
        {check.suggestion && (
          <p className="text-xs opacity-90">💡 {check.suggestion}</p>
        )}
      </div>
    </div>
  )
}
"}

{"file_path": "src/components/ats/ATSScoreCard.tsx", "initial_content": "import { CheckCircle2, AlertCircle, TrendingUp, ChevronDown, ChevronUp } from 'lucide-react'
import { ATSAnalysisResult } from '../../types/ats'
import { useState } from 'react'

interface ATSScoreCardProps {
  result: ATSAnalysisResult
  compact?: boolean
  onViewDetails?: () => void
}

export default function ATSScoreCard({ result, compact = false, onViewDetails }: ATSScoreCardProps) {
  const [isExpanded, setIsExpanded] = useState(false)

  const getScoreColor = (score: number) => {
    if (score >= 80) return 'text-green-600'
    if (score >= 60) return 'text-yellow-600'
    return 'text-red-600'
  }

  const getScoreBgColor = (score: number) => {
    if (score >= 80) return 'bg-green-100'
    if (score >= 60) return 'bg-yellow-100'
    return 'bg-red-100'
  }

  const getGradeInfo = () => {
    switch (result.grade) {
      case 'excellent':
        return { icon: CheckCircle2, text: 'Excellent', color: 'text-green-600' }
      case 'good':
        return { icon: TrendingUp, text: 'Good', color: 'text-blue-600' }
      case 'fair':
        return { icon: AlertCircle, text: 'Needs Work', color: 'text-yellow-600' }
      case 'poor':
        return { icon: AlertCircle, text: 'Needs Improvement', color: 'text-red-600' }
    }
  }

  const gradeInfo = getGradeInfo()
  const GradeIcon = gradeInfo.icon

  if (compact) {
    return (
      <button
        onClick={onViewDetails}
        className="w-full bg-white border border-gray-200 rounded-lg p-3 hover:border-primary-300 hover:shadow-md transition-all duration-200"
      >
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className={`w-12 h-12 rounded-full flex items-center justify-center ${getScoreBgColor(result.overallScore)}`}>
              <span className={`text-lg font-bold ${getScoreColor(result.overallScore)}`}>
                {result.overallScore}
              </span>
            </div>
            <div className="text-left">
              <div className="flex items-center gap-2">
                <GradeIcon className={`w-4 h-4 ${gradeInfo.color}`} />
                <span className="font-semibold text-gray-900">ATS Score: {gradeInfo.text}</span>
              </div>
              <p className="text-xs text-gray-600">
                {result.criticalIssues.length} critical • {result.warnings.length} warnings
              </p>
            </div>
          </div>
          <ChevronDown className="w-5 h-5 text-gray-400" />
        </div>
      </button>
    )
  }

  return (
    <div className="bg-white border border-gray-200 rounded-lg p-4">
      <div className="flex items-center justify-between mb-4">
        <div className="flex items-center gap-3">
          <div className={`w-16 h-16 rounded-full flex items-center justify-center ${getScoreBgColor(result.overallScore)}`}>
            <span className={`text-2xl font-bold ${getScoreColor(result.overallScore)}`}>
              {result.overallScore}
            </span>
          </div>
          <div>
            <div className="flex items-center gap-2 mb-1">
              <GradeIcon className={`w-5 h-5 ${gradeInfo.color}`} />
              <h3 className="text-lg font-semibold text-gray-900">ATS Score: {gradeInfo.text}</h3>
            </div>
            <p className="text-sm text-gray-600">
              {result.criticalIssues.length} critical issues • {result.warnings.length} warnings
            </p>
          </div>
        </div>
        <button
          onClick={() => setIsExpanded(!isExpanded)}
          className="p-2 hover:bg-gray-100 rounded-lg transition-colors"
        >
          {isExpanded ? (
            <ChevronUp className="w-5 h-5 text-gray-600" />
          ) : (
            <ChevronDown className="w-5 h-5 text-gray-600" />
          )}
        </button>
      </div>

      {isExpanded && (
        <div className="space-y-2 pt-3 border-t border-gray-200">
          {result.categoryScores.map(category => (
            <div key={category.category} className="flex items-center justify-between py-2">
              <div className="flex-1">
                <div className="flex items-center justify-between mb-1">
                  <span className="text-sm font-medium text-gray-700">{category.categoryName}</span>
                  <span className={`text-sm font-semibold ${getScoreColor(category.score)}`}>
                    {category.score}%
                  </span>
                </div>
                <div className="w-full bg-gray-200 rounded-full h-2">
                  <div
                    className={`h-2 rounded-full transition-all duration-300 ${
                      category.score >= 80 ? 'bg-green-500' : 
                      category.score >= 60 ? 'bg-yellow-500' : 'bg-red-500'
                    }`}
                    style={{ width: `${category.score}%` }}
                  />
                </div>
              </div>
            </div>
          ))}
        </div>
      )}

      {onViewDetails && (
        <button
          onClick={onViewDetails}
          className="w-full mt-4 py-2 text-sm font-medium text-primary-600 hover:text-primary-700 hover:bg-primary-50 rounded-lg transition-colors"
        >
          View Detailed Analysis
        </button>
      )}
    </div>
  )
}
"}

{"file_path": "src/components/ats/JobDescriptionInput.tsx", "initial_content": "import { useState } from 'react'
import { Briefcase, Sparkles, X, Check } from 'lucide-react'
import { JobDescription } from '../../types/ats'
import { useAI } from '../../contexts/AIContext'

interface JobDescriptionInputProps {
  onSave: (job: JobDescription | null) => void
  currentJob: JobDescription | null
}

export default function JobDescriptionInput({ onSave, currentJob }: JobDescriptionInputProps) {
  const { isConnected } = useAI()
  const [isEditing, setIsEditing] = useState(!currentJob)
  const [formData, setFormData] = useState<Partial<JobDescription>>(
    currentJob || { title: '', description: '' }
  )

  const handleSave = () => {
    if (formData.title && formData.description) {
      onSave(formData as JobDescription)
      setIsEditing(false)
    }
  }

  const handleClear = () => {
    setFormData({ title: '', description: '' })
    onSave(null)
    setIsEditing(false)
  }

  if (!isEditing && currentJob) {
    return (
      <div className="bg-gradient-to-r from-purple-50 to-blue-50 border border-purple-200 rounded-lg p-4">
        <div className="flex items-start justify-between mb-2">
          <div className="flex items-center gap-2">
            <Briefcase className="w-5 h-5 text-purple-600" />
            <h4 className="font-semibold text-gray-900">{currentJob.title}</h4>
          </div>
          <div className="flex gap-2">
            <button
              onClick={() => setIsEditing(true)}
              className="text-sm text-purple-600 hover:text-purple-700 font-medium"
            >
              Edit
            </button>
            <button
              onClick={handleClear}
              className="text-sm text-gray-500 hover:text-gray-700"
            >
              <X className="w-4 h-4" />
            </button>
          </div>
        </div>
        <p className="text-sm text-gray-600 line-clamp-2">{currentJob.description}</p>
        {isConnected && (
          <div className="flex items-center gap-2 mt-2 text-xs text-purple-600">
            <Sparkles className="w-3 h-3" />
            <span>AI analysis enabled</span>
          </div>
        )}
      </div>
    )
  }

  return (
    <div className="bg-white border border-gray-200 rounded-lg p-4">
      <div className="flex items-center gap-2 mb-3">
        <Briefcase className="w-5 h-5 text-purple-600" />
        <h4 className="font-semibold text-gray-900">Target Job (Optional)</h4>
      </div>

      <p className="text-sm text-gray-600 mb-4">
        Add a job description to get AI-powered keyword matching and skill gap analysis.
      </p>

      <div className="space-y-3">
        <div>
          <label className="label-text">Job Title</label>
          <input
            type="text"
            value={formData.title || ''}
            onChange={(e) => setFormData({ ...formData, title: e.target.value })}
            className="input-field"
            placeholder="e.g., Senior Software Engineer"
          />
        </div>

        <div>
          <label className="label-text">Job Description</label>
          <textarea
            value={formData.description || ''}
            onChange={(e) => setFormData({ ...formData, description: e.target.value })}
            className="input-field resize-none"
            rows={6}
            placeholder="Paste the job description here..."
          />
          <p className="text-xs text-gray-500 mt-1">
            Include requirements, responsibilities, and desired skills for best results.
          </p>
        </div>

        {!isConnected && (
          <div className="bg-yellow-50 border border-yellow-200 rounded-lg p-3">
            <p className="text-sm text-yellow-800">
              💡 Connect to Ollama in AI Settings to enable advanced keyword matching and skill gap analysis.
            </p>
          </div>
        )}

        <div className="flex gap-2">
          <button
            onClick={handleSave}
            disabled={!formData.title || !formData.description}
            className="btn-primary flex items-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed"
          >
            <Check className="w-4 h-4" />
            Save & Analyze
          </button>
          {currentJob && (
            <button onClick={() => setIsEditing(false)} className="btn-secondary">
              Cancel
            </button>
          )}
        </div>
      </div>
    </div>
  )
}
"}

